type I18nContextValue = {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (key: string) => string;
};

const I18nContext = createContext<I18nContextValue | null>(null);

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>("en");

  useEffect(() => {
    const stored = window.localStorage.getItem("lucy-locale");
    const nextLocale = stored === "uk" || stored === "en" ? stored : "en";
    setLocaleState(nextLocale);
    document.documentElement.lang = nextLocale === "uk" ? "uk" : "en";
  }, []);

  function setLocale(nextLocale: Locale) {
    setLocaleState(nextLocale);
    window.localStorage.setItem("lucy-locale", nextLocale);
    document.documentElement.lang = nextLocale === "uk" ? "uk" : "en";
  }

  const dictionary: Record<string, string> = { ...dictionaries[locale], ...draftOnlyOverrides[locale], "listings.workspace.saveDraft": locale === "uk" ? "Підготувати лістинг" : "Prepare Listing" };

  return (
    <I18nContext.Provider
      value={{
        locale,
        setLocale,
        t: (key) => dictionary[key] ?? key,
      }}
    >
      {children}
    </I18nContext.Provider>
  );
}

export function LanguageSwitcher() {
  const { locale, setLocale } = useI18n();

  return (
    <div role="group" aria-label="Language" className="inline-grid h-8 grid-cols-2 overflow-hidden rounded-[10px] border border-[#E7DED6] bg-white shadow-[0_4px_12px_rgba(51,51,51,0.04)]">
      <button type="button" onClick={() => setLocale("uk")} aria-pressed={locale === "uk"} className={`px-2 py-1 text-[10px] font-semibold transition-colors ${locale === "uk" ? "bg-[#F6E6DC] text-[#F26A21]" : "bg-transparent text-charcoal/40 hover:text-charcoal"}`}>
        UA
      </button>
      <button type="button" onClick={() => setLocale("en")} aria-pressed={locale === "en"} className={`px-2 py-1 text-[10px] font-semibold transition-colors ${locale === "en" ? "bg-[#F6E6DC] text-[#F26A21]" : "bg-transparent text-charcoal/40 hover:text-charcoal"}`}>
        EN
      </button>
    </div>
  );
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (!context) throw new Error("useI18n must be used inside I18nProvider");
  return context;
}
